import { ProfileRuntimeSchema } from '../types/design-profile';

export const withLaunchRuntime = (
  url: string,
  callerAgent?: string | null,
): string => {
  const target = new URL(url);
  const runtime = ProfileRuntimeSchema.safeParse(callerAgent);
  target.searchParams.set(
    'runtime',
    runtime.success ? runtime.data : 'unknown',
  );
  return target.toString();
};
